const msg = $input.item.json.messageText || '';
const hasDoc = $input.item.json.hasDocument;
const hasPhoto = $input.item.json.hasPhoto;

let messageType = 'unknown';

if (hasDoc || hasPhoto) {
  messageType = 'mill_patti';
} else if (/^add\s+party\s+/i.test(msg)) {
  messageType = 'new_party';
} else if (/^add\s+mill\s+/i.test(msg)) {
  messageType = 'new_mill';
} else if (/refuell?ed|driver\s+bata|loading\s+charge|unloading\s+charge|office\s+expense|fuel\s+expense/i.test(msg)) {
  messageType = 'expense_entry';
} else if (/lorry|AP\d{2}[A-Z]+\d+|TS\d{2}[A-Z]+\d+|TN\d{2}[A-Z]+\d+|quintal|paddy|MTU|BPT|IR64|sona/i.test(msg)) {
  messageType = 'lorry_entry';
} else if (/paid|received|rupees?|₹|cash|bank|upi|neft|rtgs|settlement/i.test(msg)) {
  messageType = 'cash_entry';
} else if (/profit/i.test(msg)) {
  messageType = 'profit_query';
} else if (/balance|outstanding|pending|due/i.test(msg)) {
  messageType = 'balance_query';
} else if (/ledger|statement|history|account/i.test(msg)) {
  messageType = 'ledger_query';
} else if (/summary|report|total|expense/i.test(msg)) {
  messageType = 'summary_query';
} else if (/show|list|all|lorry|mill|party|kirai|cut/i.test(msg)) {
  messageType = 'query';
}

return {
  ...$input.item.json,
  messageType,
  rawMessage: msg,
  todayDate: new Date().toISOString().split('T')[0]
};

