const allItems = $input.all();
const ledgerItems = allItems.filter(i => i.json.entryId);
const expenseItems = allItems.filter(i => i.json.expenseType);

const msg = $('Parse & Classify Message').item.json.rawMessage || '';
const today = new Date();
today.setHours(0, 0, 0, 0);

let startDate, endDate, label;

if (/today/i.test(msg)) {
  startDate = today; endDate = new Date(); label = 'Today';
} else if (/yesterday/i.test(msg)) {
  const y = new Date(today); y.setDate(y.getDate() - 1);
  startDate = y; endDate = new Date(y); endDate.setHours(23, 59, 59); label = 'Yesterday';
} else if (/this\s+week/i.test(msg)) {
  const w = new Date(today); w.setDate(w.getDate() - w.getDay());
  startDate = w; endDate = new Date(); label = 'This Week';
} else if (/this\s+month/i.test(msg)) {
  const m = new Date(today.getFullYear(), today.getMonth(), 1);
  startDate = m; endDate = new Date(); label = 'This Month';
} else if (/this\s+year/i.test(msg)) {
  const yr = new Date(today.getFullYear(), 0, 1);
  startDate = yr; endDate = new Date(); label = 'This Year';
} else {
  startDate = today; endDate = new Date(); label = 'Today';
}

const filtered = ledgerItems.filter(i => {
  const d = new Date(i.json.date);
  return d >= startDate && d <= endDate;
});

const totalCredits = filtered.filter(i => i.json.transactionType === 'credit').reduce((s, i) => s + Number(i.json.amount || 0), 0);
const totalDebits = filtered.filter(i => i.json.transactionType === 'debit').reduce((s, i) => s + Number(i.json.amount || 0), 0);

const filteredExp = expenseItems.filter(i => {
  const d = new Date(i.json.date);
  return d >= startDate && d <= endDate;
});
const totalExpenses = filteredExp.reduce((s, i) => s + Number(i.json.amount || 0), 0);

const profit = totalCredits - totalDebits - totalExpenses;

return {
  label,
  totalCredits,
  totalDebits,
  totalExpenses,
  profit
};

