const items = $input.all();
const msg = $('Parse & Classify Message').item.json.rawMessage || '';

const nameMatch = msg.match(/balance\s+of\s+(.+)|(.+)\s+balance|outstanding\s+(.+)|pending\s+(.+)/i);
const accountName = nameMatch ? (nameMatch[1] || nameMatch[2] || nameMatch[3] || nameMatch[4] || '').trim() : '';

const ledgerRows = items.filter(i => i.json.entryId);

let result = [];

if (accountName) {
  const filtered = ledgerRows.filter(i => i.json.accountName && i.json.accountName.toLowerCase().includes(accountName.toLowerCase()));
  const credits = filtered.filter(i => i.json.transactionType === 'credit').reduce((s, i) => s + Number(i.json.amount || 0), 0);
  const debits = filtered.filter(i => i.json.transactionType === 'debit').reduce((s, i) => s + Number(i.json.amount || 0), 0);
  const balance = credits - debits;
  result = [{ accountName, credits, debits, balance, type: filtered[0] ? filtered[0].json.accountType : 'unknown' }];
} else {
  const grouped = {};
  for (const i of ledgerRows) {
    const name = i.json.accountName;
    if (!grouped[name]) grouped[name] = { accountName: name, type: i.json.accountType, credits: 0, debits: 0 };
    if (i.json.transactionType === 'credit') grouped[name].credits += Number(i.json.amount || 0);
    else grouped[name].debits += Number(i.json.amount || 0);
  }
  result = Object.values(grouped).map(g => ({ ...g, balance: g.credits - g.debits })).filter(g => g.balance !== 0);
}

return { result, accountName, isSpecific: !!accountName };

const { result, accountName, isSpecific } = $input.item.json;

let text = '';

if (isSpecific && result.length > 0) {
  const r = result[0];
  const balLabel = r.balance >= 0 ? 'Credit' : 'Debit';
  text = `💰 Balance Report\n\n${r.type === 'mill' ? '🏭' : '👤'} ${r.accountName}\n\n`;
  text += `Total Credits: ₹${r.credits.toLocaleString('en-IN')}\n`;
  text += `Total Debits: ₹${r.debits.toLocaleString('en-IN')}\n`;
  text += `─────────────────\n`;
  text += `Current Balance: ₹${Math.abs(r.balance).toLocaleString('en-IN')} ${balLabel}`;
} else if (!isSpecific && result.length > 0) {
  text = `📊 Outstanding Balances\n\n`;
  const parties = result.filter(r => r.type === 'party' && r.balance !== 0);
  const mills = result.filter(r => r.type === 'mill' && r.balance !== 0);
  if (parties.length > 0) {
    text += `👤 Parties:\n`;
    parties.forEach(p => { text += `  ${p.accountName}: ₹${Math.abs(p.balance).toLocaleString('en-IN')} ${p.balance >= 0 ? 'Cr' : 'Dr'}\n`; });
  }
  if (mills.length > 0) {
    text += `\n🏭 Mills:\n`;
    mills.forEach(m => { text += `  ${m.accountName}: ₹${Math.abs(m.balance).toLocaleString('en-IN')} ${m.balance >= 0 ? 'Cr' : 'Dr'}\n`; });
  }
} else {
  text = `⚠️ No balance data found${accountName ? ' for ' + accountName : ''}.`;
}

return { balanceText: text };

